import type { ToolRecord } from "../registry/types.js";
import { DeterministicToolScorer, MIN_RELEVANT_SCORE, queryTokenize, type PreparedTool, type ToolScorer } from "./scorer.js";
import { uniqueTokens } from "./tokenize.js";

/**
 * Discovery result shape (spec §5). Deliberately NOT the full JSON schema —
 * schemas stay out of model context until describe_tool asks for one.
 */
export interface DiscoveryResult {
  toolRef: string;
  server: string;
  name: string;
  description?: string;
  score: number;
  tags: string[];
  requiresAuth: boolean;
  inputSchema?: unknown;
}

export interface RelevantSearchOptions {
  context: string;
  limit?: number;
  server?: string;
  tags?: string[];
  includeSchemas?: boolean;
}

export interface AllOptions {
  limit: number;
  offset?: number;
  server?: string;
  tags?: string[];
}

export interface Page<T> {
  results: T[];
  total: number;
  offset: number;
  nextOffset?: number;
}

export interface ToolCatalog {
  /** Replace one server's tools (used at startup and per-server reload). */
  replaceServerTools(serverId: string, records: ToolRecord[], requiresAuth: boolean): void;
  removeServer(serverId: string): void;
  /** Rebuild derived index state. Call after a batch of mutations. */
  commit(): void;
  size(): number;
  serverIds(): string[];
  toolCountFor(serverId: string): number;
  get(ref: string): ToolRecord | undefined;
  searchRelevant(opts: RelevantSearchOptions): DiscoveryResult[];
  all(opts: AllOptions): Page<DiscoveryResult>;
  /** Sum of downstream schema sizes — for benchmarks/reporting. */
  approximateSchemaBytes(): number;
}

interface CatalogEntry {
  record: ToolRecord;
  prepared: PreparedTool;
  requiresAuth: boolean;
}

export class InMemoryToolCatalog implements ToolCatalog {
  private entries = new Map<string, CatalogEntry>();
  private byRef = new Map<string, CatalogEntry>();
  private df = new Map<string, number>();
  private scorer: DeterministicToolScorer;
  private dirty = true;

  constructor(scorer?: ToolScorer) {
    // The catalog fast-path needs the deterministic scorer's prepared docs;
    // alternate scorers plug in through searchRelevant's fallback below.
    this.scorer = (scorer as DeterministicToolScorer | undefined) ?? new DeterministicToolScorer();
  }

  replaceServerTools(serverId: string, records: ToolRecord[], requiresAuth: boolean): void {
    this.removeServer(serverId);
    for (const record of records) {
      this.entries.set(record.ref, {
        record,
        prepared: this.scorer.prepare(record),
        requiresAuth,
      });
    }
    this.dirty = true;
  }

  removeServer(serverId: string): void {
    for (const [ref, entry] of this.entries) {
      if (entry.record.serverId === serverId) this.entries.delete(ref);
    }
    this.dirty = true;
  }

  commit(): void {
    this.byRef = new Map(this.entries);
    this.df = new Map();
    for (const entry of this.entries.values()) {
      for (const token of uniqueTokens(entry.prepared.allTokens)) {
        this.df.set(token, (this.df.get(token) ?? 0) + 1);
      }
    }
    this.dirty = false;
  }

  private ensureCommitted(): void {
    if (this.dirty) this.commit();
  }

  size(): number {
    return this.entries.size;
  }

  serverIds(): string[] {
    return [...new Set([...this.entries.values()].map((e) => e.record.serverId))];
  }

  toolCountFor(serverId: string): number {
    let n = 0;
    for (const e of this.entries.values()) if (e.record.serverId === serverId) n += 1;
    return n;
  }

  get(ref: string): ToolRecord | undefined {
    this.ensureCommitted();
    return this.byRef.get(ref)?.record;
  }

  searchRelevant(opts: RelevantSearchOptions): DiscoveryResult[] {
    this.ensureCommitted();
    const queryTokens = queryTokenize(opts.context);
    if (queryTokens.length === 0) return [];

    const stats = {
      docCount: this.entries.size,
      df: (term: string) => this.df.get(term) ?? 0,
    };

    const scored: Array<{ entry: CatalogEntry; score: number }> = [];
    for (const entry of this.entries.values()) {
      if (opts.server && entry.record.serverId !== opts.server) continue;
      if (opts.tags?.length && !opts.tags.some((t) => entry.record.tags.includes(t))) continue;
      const score = this.scorer.scorePrepared(queryTokens, entry.prepared, stats);
      if (score >= MIN_RELEVANT_SCORE) scored.push({ entry, score });
    }

    scored.sort((a, b) => (b.score - a.score) || a.entry.record.ref.localeCompare(b.entry.record.ref));
    const limit = Math.max(1, opts.limit ?? 10);
    return scored.slice(0, limit).map(({ entry, score }) => this.toResult(entry, score, opts.includeSchemas));
  }

  all(opts: AllOptions): Page<DiscoveryResult> {
    this.ensureCommitted();
    const filtered = [...this.entries.values()]
      .filter((e) => (opts.server ? e.record.serverId === opts.server : true))
      .filter((e) => (opts.tags?.length ? opts.tags.some((t) => e.record.tags.includes(t)) : true))
      .sort((a, b) => a.record.ref.localeCompare(b.record.ref));

    const offset = Math.max(0, opts.offset ?? 0);
    const limit = Math.max(1, opts.limit);
    const slice = filtered.slice(offset, offset + limit);
    const nextOffset = offset + slice.length < filtered.length ? offset + slice.length : undefined;
    return {
      results: slice.map((e) => this.toResult(e, 0, false)),
      total: filtered.length,
      offset,
      nextOffset,
    };
  }

  approximateSchemaBytes(): number {
    let bytes = 0;
    for (const e of this.entries.values()) {
      bytes += JSON.stringify(e.record.inputSchema ?? {}).length;
    }
    return bytes;
  }

  /** All catalog records (sorted by ref) — used for flat tools/list. */
  listRecords(): ToolRecord[] {
    this.ensureCommitted();
    return [...this.entries.values()]
      .map((e) => e.record)
      .sort((a, b) => a.ref.localeCompare(b.ref));
  }

  private toResult(entry: CatalogEntry, score: number, includeSchemas?: boolean): DiscoveryResult {
    const r = entry.record;
    return {
      toolRef: r.ref,
      server: r.serverId,
      name: r.name,
      description: r.description,
      score: Math.round(score * 1000) / 1000,
      tags: r.tags,
      requiresAuth: entry.requiresAuth,
      ...(includeSchemas ? { inputSchema: r.inputSchema } : {}),
    };
  }
}
