#!/usr/bin/env node
/**
 * CLI entry point (spec §22).
 *
 * Two kinds of commands:
 *  - CLI mode (init/login/status/…): normal terminal stdout is fine.
 *  - serve mode: stdout is reserved for MCP JSON-RPC (spec §20).
 */
import { Command } from "commander";
import { initCommand } from "./commands/init.js";
import { loginCommand } from "./commands/login.js";
import { authStatusCommand, logoutCommand } from "./commands/auth.js";
import { serveCommand } from "./commands/serve.js";
import { reloadCommand } from "./commands/reload.js";
import { statusCommand } from "./commands/status.js";
import { serversCommand } from "./commands/servers.js";
import { toolsCommand } from "./commands/tools.js";
import { doctorCommand } from "./commands/doctor.js";
import { pluginInstallCommand } from "./commands/plugin.js";
import { upCommand } from "./commands/up.js";
import { productName } from "../product-name.js";

const program = new Command();

program
  .name(productName())
  .description("Local MCP router — one server for the host, hundreds downstream")
  .version("0.1.0");

program
  .command("init")
  .description("Create a starter registry config")
  .option("--config <path>", "where to write the config")
  .option("--force", "overwrite an existing config")
  .action((opts) => initCommand(opts));

program
  .command("login")
  .description("Authenticate against Cognito (password never leaves this process except to Cognito)")
  .option("--config <path>", "config file")
  .option("--tenant <name>", "tenant to log into (default: activeTenant)")
  .option("--username <username>", "username (otherwise prompted)")
  .option("--password-stdin", "read the password from piped stdin instead of prompting")
  .option(
    "--apikey [key]",
    "base64 JSON {username,password,tenant}; headless password login, or with --browser uses tenant only; omit value for HIREKO_INTERNAL_API_KEY",
  )
  .option("--browser", "Open /devicelogin (username/password → local CLI; does not sign into SPA)")
  .option("--stage <beta|prod>", "tenant config host (default: plugin deploy / HIREKO_STAGE)")
  .option("--local-port <port>", "local Vite dashboard port → http://127.0.0.1:<port>/devicelogin")
  .option("--device-login-origin <url>", "dashboard origin override (takes precedence over --local-port)")
  .option("--redirect-uri <url>", "unused for device login (kept for compatibility)")
  .option("--no-open-browser", "do not open the default browser (device login URL is always printed)")
  .action((opts) => loginCommand(opts));

program
  .command("logout")
  .description("Remove stored tokens")
  .option("--config <path>", "config file")
  .option("--tenant <name>", "tenant to log out of (default: activeTenant)")
  .action((opts) => logoutCommand(opts));

const auth = program.command("auth").description("Authentication commands");
auth
  .command("status")
  .description("Show authentication status")
  .option("--config <path>", "config file")
  .action((opts) => authStatusCommand(opts));

program
  .command("serve")
  .description("Run the local MCP server (stdio by default; --detach for daemon + HTTP MCP)")
  .option("--config <path>", "config file")
  .option("--detach", "daemon mode: /human + HTTP MCP on :8400, no stdio parent")
  .action((opts) => serveCommand(opts));

program
  .command("up")
  .description("Clear orphan detached proxies (MCP is harness-owned via stdio)")
  .option("--config <path>", "config file")
  .option("--restart", "same as default — clear orphans")
  .option("--json", "machine-readable output")
  .action((opts) => upCommand(opts));

program
  .command("reload")
  .description("Validate config and signal a running serve process to hot-reload")
  .option("--config <path>", "config file")
  .action((opts) => reloadCommand(opts));

program
  .command("status")
  .description("Overview: auth, servers, indexed tools")
  .option("--config <path>", "config file")
  .option("--json", "machine-readable output")
  .action((opts) => statusCommand(opts));

program
  .command("servers")
  .description("List downstream servers with health and tool counts")
  .option("--config <path>", "config file")
  .option("--json", "machine-readable output")
  .action((opts) => serversCommand(opts));

const tools = program
  .command("tools")
  .description("Inspect the indexed tool catalog")
  .argument("[context]", "natural-language search context")
  .option("--config <path>", "config file")
  .option("--limit <n>", "max results", "10")
  .option("--server <id>", "restrict to one server")
  .option("--json", "machine-readable output")
  .action((context, opts) => toolsCommand(context, opts));

const plugin = program.command("plugin").description("Agent-plugin distribution (private S3, SSO + SigV4)");
plugin
  .command("install")
  .description("Fetch, verify, and install the plugin from a private S3 bucket — all steps internal")
  .argument("<s3Uri>", "s3://<bucket>/<plugin>-x.y.z.zip")
  .option("--profile <name>", "AWS profile to use instead of SSO bootstrap")
  .option("--no-register", "skip host MCP registration")
  .action((s3Uri, opts) => pluginInstallCommand(s3Uri, { profile: opts.profile, noRegister: opts.register === false }));

program
  .command("doctor")
  .description("Diagnose environment, config, auth, and fleet health")
  .option("--config <path>", "config file")
  .action((opts) => doctorCommand(opts));

program.parseAsync(process.argv).catch((err) => {
  console.error(`✗ ${err instanceof Error ? err.message : String(err)}`);
  process.exit(1);
});
