import { createHash, randomBytes } from "node:crypto";

/** RFC 7636 PKCE helpers for Cognito Hosted UI (authorization code + S256). */

export function generateCodeVerifier(): string {
  return randomBytes(32).toString("base64url");
}

export function codeChallengeS256(verifier: string): string {
  return createHash("sha256").update(verifier).digest("base64url");
}

export function generateOAuthState(): string {
  return randomBytes(16).toString("base64url");
}

export interface CognitoOAuthEndpoints {
  authorizeUrl: string;
  tokenUrl: string;
}

/** `domain` is the Hosted UI hostname without scheme. */
export function cognitoOAuthEndpoints(domain: string): CognitoOAuthEndpoints {
  const host = domain.replace(/^https?:\/\//, "").replace(/\/$/, "");
  return {
    authorizeUrl: `https://${host}/oauth2/authorize`,
    tokenUrl: `https://${host}/oauth2/token`,
  };
}

export function buildAuthorizeUrl(params: {
  domain: string;
  clientId: string;
  redirectUri: string;
  scopes: string[];
  state: string;
  codeChallenge: string;
}): string {
  const { authorizeUrl } = cognitoOAuthEndpoints(params.domain);
  const q = new URLSearchParams({
    response_type: "code",
    client_id: params.clientId,
    redirect_uri: params.redirectUri,
    scope: params.scopes.join(" "),
    state: params.state,
    code_challenge: params.codeChallenge,
    code_challenge_method: "S256",
  });
  return `${authorizeUrl}?${q.toString()}`;
}

export interface OAuthTokenResponse {
  access_token: string;
  id_token?: string;
  refresh_token?: string;
  expires_in?: number;
  token_type?: string;
}

export async function exchangeAuthorizationCode(params: {
  domain: string;
  clientId: string;
  code: string;
  redirectUri: string;
  codeVerifier: string;
  clientSecret?: string;
}): Promise<OAuthTokenResponse> {
  const { tokenUrl } = cognitoOAuthEndpoints(params.domain);
  const body = new URLSearchParams({
    grant_type: "authorization_code",
    client_id: params.clientId,
    code: params.code,
    redirect_uri: params.redirectUri,
    code_verifier: params.codeVerifier,
  });
  if (params.clientSecret) body.set("client_secret", params.clientSecret);

  const res = await fetch(tokenUrl, {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body: body.toString(),
  });
  const text = await res.text();
  if (!res.ok) {
    throw new Error(`Cognito token exchange failed (${res.status}): ${text}`);
  }
  return JSON.parse(text) as OAuthTokenResponse;
}

/** Best-effort username from Cognito id_token (no signature verify — display only). */
export function usernameFromIdToken(idToken: string | undefined): string | undefined {
  if (!idToken) return undefined;
  try {
    const payload = idToken.split(".")[1];
    if (!payload) return undefined;
    const json = JSON.parse(Buffer.from(payload, "base64url").toString("utf8")) as Record<string, unknown>;
    const email = typeof json.email === "string" ? json.email : undefined;
    const sub = typeof json.sub === "string" ? json.sub : undefined;
    const cognitoUsername =
      typeof json["cognito:username"] === "string" ? (json["cognito:username"] as string) : undefined;
    return email ?? cognitoUsername ?? sub;
  } catch {
    return undefined;
  }
}
