import type { AppConfig } from "../config/schema.js";
import type { TokenProvider } from "../auth/types.js";

/**
 * Forwarded-header templates (spec §16). All HTTP auth injection flows
 * through this one layer.
 *
 * Template variables:
 *   ${TOKEN}        — the tenant's forwarded token (per tokenToForward)
 *   ${ACCESS_TOKEN} — the Cognito access token
 *   ${ID_TOKEN}     — the Cognito ID token
 *   ${TENANT}       — the active tenant name
 *
 * When `authHeaders` is not configured, the default is
 * `Authorization: Bearer ${TOKEN}`.
 */
export interface HeaderSpec {
  name: string;
  valueTemplate: string;
}

/** Headers the model (and static per-server config) may never override. */
export const PROTECTED_HEADERS = new Set(["authorization", "cookie", "x-tenant"]);

export function parseHeaderSpecs(config: AppConfig): HeaderSpec[] {
  if (!config.authHeaders || Object.keys(config.authHeaders).length === 0) {
    return [{ name: "authorization", valueTemplate: "Bearer ${TOKEN}" }];
  }
  const specs: HeaderSpec[] = [];
  for (const [key, value] of Object.entries(config.authHeaders)) {
    if (typeof value === "string") {
      specs.push({ name: key, valueTemplate: value });
    } else {
      specs.push({ name: value.name, valueTemplate: value.value });
    }
  }
  return specs;
}

export interface TemplateContext {
  tokenProvider: TokenProvider;
  tenantName: string;
}

export async function resolveTemplate(template: string, ctx: TemplateContext): Promise<string> {
  const vars: Record<string, () => Promise<string>> = {
    TOKEN: () => ctx.tokenProvider.getAccessToken(),
    ACCESS_TOKEN: () => ctx.tokenProvider.getToken("access"),
    ID_TOKEN: () => ctx.tokenProvider.getToken("id"),
    TENANT: async () => ctx.tenantName,
  };
  let out = template;
  for (const [name, resolve] of Object.entries(vars)) {
    if (out.includes(`\${${name}}`)) {
      out = out.split(`\${${name}}`).join(await resolve());
    }
  }
  return out;
}

/** True when a server URL or stdio env interpolates the active tenant. */
export function usesTenantPlaceholder(server: { url?: string; env?: Record<string, string> }): boolean {
  if (server.url?.includes("${TENANT}")) return true;
  if (server.env && Object.values(server.env).some((v) => v.includes("${TENANT}"))) return true;
  return false;
}

/** Substitute ${TENANT} in a downstream URL. Tenant is encoded as a path/query segment. */
export function expandUrlTemplates(url: string, tenantName: string): string {
  if (!url.includes("${TENANT}")) return url;
  return url.split("${TENANT}").join(encodeURIComponent(tenantName));
}

export async function resolveHeaders(specs: HeaderSpec[], ctx: TemplateContext): Promise<Record<string, string>> {
  const headers: Record<string, string> = {};
  for (const spec of specs) {
    headers[spec.name] = await resolveTemplate(spec.valueTemplate, ctx);
  }
  return headers;
}
