/**
 * Canonical tool identity (spec §8): `<serverId>.<toolName>`. Downstream tool
 * names are NEVER assumed globally unique.
 */
export interface ToolRecord {
  ref: string;
  serverId: string;
  name: string;
  title?: string;
  description?: string;
  /** Optional group/server blurb from config (used in filter + host description). */
  groupDescription?: string;
  inputSchema: unknown;
  annotations?: unknown;
  tags: string[];
  /** Pre-joined lowercase text for search. */
  searchableText: string;
}

export function makeRef(serverId: string, toolName: string): string {
  return `${serverId}.${toolName}`;
}

export function parseRef(ref: string): { serverId: string; name: string } | undefined {
  const dot = ref.indexOf(".");
  if (dot <= 0 || dot === ref.length - 1) return undefined;
  return { serverId: ref.slice(0, dot), name: ref.slice(dot + 1) };
}

export type ServerStatus = "unknown" | "connecting" | "healthy" | "unavailable";

export interface ServerHealth {
  serverId: string;
  status: ServerStatus;
  toolCount: number;
  lastError?: string;
  lastCheckedAt?: number;
}
