import {
  CognitoIdentityProviderClient,
  InitiateAuthCommand,
  RespondToAuthChallengeCommand,
  RevokeTokenCommand,
  GlobalSignOutCommand,
  type AuthFlowType,
} from "@aws-sdk/client-cognito-identity-provider";
import type { CognitoConfig } from "../config/schema.js";

/**
 * Minimal Cognito surface used by Hireko, behind an interface so tests can
 * inject fakes (spec §31) and a future IdP can replace Cognito entirely.
 */
export interface CognitoTokenResult {
  accessToken?: string;
  idToken?: string;
  refreshToken?: string;
  expiresInSec?: number;
  tokenType?: string;
}

export interface CognitoChallengeResult {
  challengeName: string;
  session?: string;
  parameters?: Record<string, string>;
}

export type CognitoAuthResult =
  | { kind: "tokens"; tokens: CognitoTokenResult }
  | { kind: "challenge"; challenge: CognitoChallengeResult };

export interface CognitoApi {
  initiateAuth(params: {
    authFlow: AuthFlowType;
    clientId: string;
    authParameters: Record<string, string>;
  }): Promise<CognitoAuthResult>;

  respondToAuthChallenge(params: {
    clientId: string;
    challengeName: string;
    session?: string;
    challengeResponses: Record<string, string>;
  }): Promise<CognitoAuthResult>;

  /**
   * Revoke a refresh token (and its token family when Cognito rotation is on).
   * Best practice on logout so a stolen refresh cannot mint new access tokens.
   */
  revokeToken(params: {
    clientId: string;
    clientSecret?: string;
    refreshToken: string;
  }): Promise<void>;

  /** Invalidate all tokens issued to this user (requires a still-valid access token). */
  globalSignOut(params: { accessToken: string }): Promise<void>;
}

/** Real AWS SDK v3 adapter (spec §13). */
export class SdkCognitoApi implements CognitoApi {
  private readonly client: CognitoIdentityProviderClient;

  constructor(private readonly config: CognitoConfig) {
    this.client = new CognitoIdentityProviderClient({ region: config.region });
  }

  async initiateAuth(params: {
    authFlow: AuthFlowType;
    clientId: string;
    authParameters: Record<string, string>;
  }): Promise<CognitoAuthResult> {
    const out = await this.client.send(
      new InitiateAuthCommand({
        AuthFlow: params.authFlow,
        ClientId: params.clientId,
        AuthParameters: params.authParameters,
      }),
    );
    return toResult(out.ChallengeName, out.Session, out.ChallengeParameters, out.AuthenticationResult);
  }

  async respondToAuthChallenge(params: {
    clientId: string;
    challengeName: string;
    session?: string;
    challengeResponses: Record<string, string>;
  }): Promise<CognitoAuthResult> {
    const out = await this.client.send(
      new RespondToAuthChallengeCommand({
        ClientId: params.clientId,
        ChallengeName: params.challengeName as never,
        Session: params.session,
        ChallengeResponses: params.challengeResponses,
      }),
    );
    return toResult(out.ChallengeName, out.Session, out.ChallengeParameters, out.AuthenticationResult);
  }

  async revokeToken(params: {
    clientId: string;
    clientSecret?: string;
    refreshToken: string;
  }): Promise<void> {
    await this.client.send(
      new RevokeTokenCommand({
        ClientId: params.clientId,
        ClientSecret: params.clientSecret,
        Token: params.refreshToken,
      }),
    );
  }

  async globalSignOut(params: { accessToken: string }): Promise<void> {
    await this.client.send(new GlobalSignOutCommand({ AccessToken: params.accessToken }));
  }
}

function toResult(
  challengeName: string | undefined,
  session: string | undefined,
  challengeParameters: Record<string, string> | undefined,
  authResult?: {
    AccessToken?: string;
    IdToken?: string;
    RefreshToken?: string;
    ExpiresIn?: number;
    TokenType?: string;
  },
): CognitoAuthResult {
  if (challengeName) {
    return {
      kind: "challenge",
      challenge: { challengeName, session, parameters: challengeParameters },
    };
  }
  return {
    kind: "tokens",
    tokens: {
      accessToken: authResult?.AccessToken,
      idToken: authResult?.IdToken,
      refreshToken: authResult?.RefreshToken,
      expiresInSec: authResult?.ExpiresIn,
      tokenType: authResult?.TokenType,
    },
  };
}
