import { AuthScopeProvider } from "./auth/auth-scope-provider.js";
import { resolveTenantCognito, TenantAuthUnresolvedError } from "./auth/tenant-cognito-resolver.js";
import { CatalogCache } from "./catalog/cache.js";
import { InMemoryToolCatalog } from "./catalog/catalog.js";
import { SdkCognitoApi, type CognitoApi } from "./auth/cognito.js";
import { createDefaultCredentialStore, type CredentialStore } from "./auth/credential-store.js";
import type { TokenManager } from "./auth/token-manager.js";
import { JsonRegistryLoader, loadConfig, type RegistryLoader } from "./config/loader.js";
import { updateConfigFile } from "./config/writer.js";
import type { AppConfig, CognitoConfig } from "./config/schema.js";
import { catalogCachePath } from "./config/paths.js";
import { rootLogger, type Logger } from "./logging/logger.js";
import { RouterCore } from "./mcp/core.js";
import { ActivationSession } from "./mcp/session.js";
import { parseHeaderSpecs } from "./proxy/headers.js";
import { ServerRegistry } from "./registry/registry.js";
import { HirekoTransportFactory, type ResolvedAuth } from "./transports/factory.js";

/**
 * One place where the whole app is assembled. `hireko serve`, one-shot CLI
 * commands, tests, and the demo all go through this.
 *
 * Multi-tenancy: auth resolution is runtime and per-tenant via
 * AuthScopeProvider — each tenant carries its own Cognito configuration.
 * The serve process routes tools for the config's `activeTenant`; sessions
 * for other tenants can still be established (login/status/logout).
 */
export interface App {
  configPath: string;
  getConfig(): AppConfig;
  tenantName: string;
  /** Runtime multi-tenant auth resolution. */
  authScopeProvider: AuthScopeProvider;
  /** Token provider for the active (served) tenant at boot. */
  tokenProvider: TokenManager;
  /** Live per-request auth resolution (current activeTenant). */
  resolveAuth: () => Promise<ResolvedAuth>;
  registry: ServerRegistry;
  catalog: InMemoryToolCatalog;
  core: RouterCore;
  session: ActivationSession;
  logger: Logger;
  /** Persist config activeTenant (file when possible; in-memory fallback). */
  setActiveTenant(tenant: string): Promise<void>;
  close(): Promise<void>;
}

export interface BootstrapOptions {
  configPath?: string;
  logger?: Logger;
  /** Test seams. */
  loader?: RegistryLoader;
  credentialStore?: CredentialStore;
  cognitoApiFactory?: (cognito: CognitoConfig) => CognitoApi;
  /** Test seam: override tenant→Cognito resolution. */
  resolveTenantCognito?: (tenant: string) => Promise<CognitoConfig>;
  /** Skip the optional catalog cache (tests/benchmarks). */
  disableCache?: boolean;
  /** Skip downstream discovery (used when caller drives it). */
  skipDiscovery?: boolean;
}

export async function bootstrap(opts: BootstrapOptions = {}): Promise<App> {
  const logger = opts.logger ?? rootLogger;
  const loader = opts.loader ?? new JsonRegistryLoader();

  const { config, path: configPath } = await loadConfig(loader, opts.configPath);
  const tenantName = config.activeTenant;

  const store = opts.credentialStore ?? (await createDefaultCredentialStore());

  // Registry reference is wired lazily so the provider always reads the
  // CURRENT config (reload-safe runtime resolution) without a cycle.
  let registryInstance: ServerRegistry | undefined;
  const authScopeProvider = new AuthScopeProvider({
    getConfig: () => registryInstance?.currentConfig ?? config,
    store,
    logger,
    cognitoApiFactory: opts.cognitoApiFactory ?? ((c) => new SdkCognitoApi(c)),
    resolveTenantCognito:
      opts.resolveTenantCognito ??
      (async (t) => {
        // Prefer public tenant_configuration.json (and session authStage via store).
        // Fall back to optional config.tenants catalog for offline/tests.
        try {
          return await resolveTenantCognito(t, { store });
        } catch (err) {
          const current = registryInstance?.currentConfig ?? config;
          const tenantConfig = current.tenants?.[t];
          if (tenantConfig?.cognito) return tenantConfig.cognito;
          if (err instanceof TenantAuthUnresolvedError) throw err;
          throw new TenantAuthUnresolvedError(
            err instanceof Error ? err.message : "tenant Cognito resolution failed",
          );
        }
      }),
  });

  const tokenProvider = await authScopeProvider.tokenProviderFor(tenantName);

  // Live auth resolution: reads the CURRENT config's activeTenant on every
  // downstream request, so /human tenant switches apply without a restart.
  const resolveAuth = async (): Promise<ResolvedAuth> => {
    const current = registryInstance?.currentConfig ?? config;
    return {
      tokenProvider: await authScopeProvider.tokenProviderFor(current.activeTenant),
      tenantName: current.activeTenant,
      headerSpecs: parseHeaderSpecs(current),
    };
  };
  const transportFactory = new HirekoTransportFactory({ resolveAuth, logger });

  const catalog = new InMemoryToolCatalog();
  const cache = opts.disableCache ? undefined : new CatalogCache(catalogCachePath(), logger);

  const registry = new ServerRegistry({
    config,
    configPath,
    loader,
    transportFactory,
    catalog,
    cache,
    logger,
  });
  registryInstance = registry;

  const session = new ActivationSession();
  const setActiveTenant = async (tenant: string): Promise<void> => {
    const name = tenant.trim();
    if (!name) throw new Error("tenant name is required");
    const current = registry.currentConfig;
    if (current.activeTenant === name) return;
    try {
      const parsed = await updateConfigFile(configPath, (raw) => {
        raw.activeTenant = name;
        return raw;
      });
      await registry.reload({ config: parsed, path: configPath });
    } catch {
      await registry.reload({ config: { ...current, activeTenant: name }, path: configPath });
    }
  };
  const core = new RouterCore({
    getConfig: () => registry.currentConfig,
    registry,
    catalog,
    getTokenProvider: () => resolveAuth().then((a) => a.tokenProvider),
    authScopeProvider,
    setActiveTenant,
    session,
    logger,
  });

  if (!opts.skipDiscovery) {
    await registry.startup();
  }

  return {
    configPath,
    getConfig: () => registry.currentConfig,
    tenantName,
    authScopeProvider,
    tokenProvider,
    resolveAuth,
    registry,
    catalog,
    core,
    session,
    logger,
    setActiveTenant,
    close: async () => {
      await registry.shutdown();
    },
  };
}
