import { readFile, writeFile, mkdir, unlink } from "node:fs/promises";
import { dirname } from "node:path";
import { createHash } from "node:crypto";
import type { ServerConfig } from "../config/schema.js";
import type { ToolRecord } from "../registry/types.js";
import type { Logger } from "../logging/logger.js";

/**
 * Optional startup-only catalog snapshot (spec §24). Disposable: deleting it
 * must never break the system, and it never contains auth tokens.
 */
export interface CatalogSnapshot {
  version: 1;
  savedAt: string;
  servers: Record<string, { fingerprint: string; toolCount: number }>;
  tools: Array<ToolRecord & { requiresAuth: boolean }>;
}

export function serverFingerprint(server: ServerConfig): string {
  const material = JSON.stringify({
    transport: server.transport,
    url: server.url,
    command: server.command,
    args: server.args,
    enabled: server.enabled,
    tags: server.tags,
  });
  return createHash("sha256").update(material).digest("hex").slice(0, 16);
}

export class CatalogCache {
  constructor(
    private readonly path: string,
    private readonly logger: Logger,
  ) {}

  async load(): Promise<CatalogSnapshot | undefined> {
    try {
      const raw = await readFile(this.path, "utf8");
      const parsed = JSON.parse(raw) as CatalogSnapshot;
      if (parsed.version !== 1 || !Array.isArray(parsed.tools)) return undefined;
      return parsed;
    } catch {
      return undefined;
    }
  }

  /** Tools for servers whose fingerprint still matches; stale ones skipped. */
  freshTools(snapshot: CatalogSnapshot, servers: Map<string, ServerConfig>): Array<ToolRecord & { requiresAuth: boolean }> {
    return snapshot.tools.filter((t) => {
      const server = servers.get(t.serverId);
      const recorded = snapshot.servers[t.serverId];
      return Boolean(server && server.enabled && recorded && recorded.fingerprint === serverFingerprint(server));
    });
  }

  async save(snapshot: CatalogSnapshot): Promise<void> {
    try {
      await mkdir(dirname(this.path), { recursive: true });
      await writeFile(this.path, JSON.stringify(snapshot));
    } catch (err) {
      this.logger.debug("catalog cache write failed", { error: (err as Error).message });
    }
  }

  async clear(): Promise<void> {
    await unlink(this.path).catch(() => {});
  }
}
